def canonical_target_header_sha256(target_header):
 canonical_header={
  str(key):(value if value is None or isinstance(value,(bool,int,float,str)) else str(value))
  for key,value in target_header.items()
 }
 return hashlib.sha256(json.dumps(canonical_header,sort_keys=True,separators=(",",":")).encode("utf-8")).hexdigest()

def verify_target_header_binding(batch,declared_sha256,file_sha256,canonical_json_sha256):
