def finite_json(value,path="$",missing=None):
 if missing is None:missing=[]
 if isinstance(value,float) and not math.isfinite(value):
  missing.append({"path":path,"original_value":repr(value)})
  return None
 if isinstance(value,dict):return {key:finite_json(item,path+"."+str(key),missing) for key,item in value.items()}
 if isinstance(value,(list,tuple)):return [finite_json(item,path+"["+str(index)+"]",missing) for index,item in enumerate(value)]
 return value

class OutputJSON:
 def __getattr__(self,name):return getattr(json,name)
 def dumps(self,value,*args,**kwargs):
  if isinstance(value,dict) and "per_method" in value and "selection_rule" in value:
   missing=[];value=finite_json(value,missing=missing)
   value["serialization_audit"]={"policy":"Unavailable non-finite summary values are null, with original fields recorded; scorer algorithms and gates are unchanged.","nonfinite_fields":missing}
   (output/"nonfinite-fields.json").write_text(json.dumps(missing,indent=2,allow_nan=False)+"\n")
  return json.dumps(value,*args,**kwargs)

